@Entity
class Customer {
    @Version
    private Long version;

    boolean promoteIfEligible(int min) {          // logic nằm trong entity
        if (tier == Tier.SILVER && points >= min) {
            tier = Tier.GOLD;
            return true;
        }
        return false;
    }
}

@Service
class OrderCompletionService {
    @Transactional
    public void complete(long orderId) {
        Order order = orders.findById(orderId).orElseThrow();
        Customer customer = customers.findById(order.getCustomerId()).orElseThrow();
        customer.promoteIfEligible(1_000);
        customer.setLastOrderAt(Instant.now());
        order.markCompleted();
    }   // một UPDATE customer ... where id=? and version=?
}
